INSERT IGNORE INTO obra (id, titulo, tipo, ano, status, nota, popularidade, episodios, estudio, autor, duracao, plataformas_nota, sinopse, capa, banner) VALUES ('frieren', 'Frieren: Beyond Journey''s End', 'anime', 2023, 'finalizado', 9.3, 98, 28, 'Madhouse', 'Kanehito Yamada e Tsukasa Abe', '24 min por episódio', 'streaming pode variar por região e assinatura.', 'após derrotar o rei demônio, a elfa Frieren segue vivendo enquanto seus antigos companheiros envelhecem. Entre memórias, magia e novas viagens, ela aprende tarde demais o peso dos laços que deixou passar.', 'https://cdn.myanimelist.net/images/anime/1015/138006.jpg', 'https://cdn.myanimelist.net/images/anime/1015/138006l.jpg');
