INSERT IGNORE INTO obra (id, titulo, tipo, ano, status, nota, popularidade, episodios, estudio, autor, duracao, plataformas_nota, sinopse, capa, banner) VALUES ('solo-leveling', 'Solo Leveling', 'manhwa', 2018, 'finalizado', 8.7, 96, 200, 'A-1 Pictures', 'Chugong e DUBU', '24 min por episódio', 'o anime está disponível legalmente no Brasil via Crunchyroll; leitura pode variar por idioma/região.', 'Sung Jinwoo é conhecido como o caçador mais fraco, até sobreviver a uma dungeon impossível e ser escolhido por um sistema misterioso. Agora, cada batalha pode torná-lo mais forte do que qualquer outro humano.', 'https://cdn.myanimelist.net/images/manga/3/222295.jpg', 'https://cdn.myanimelist.net/images/manga/3/222295l.jpg');
