INSERT IGNORE INTO obra (id, titulo, tipo, ano, status, nota, popularidade, episodios, estudio, autor, duracao, plataformas_nota, sinopse, capa, banner) VALUES ('demon-slayer', 'Demon Slayer', 'anime', 2019, 'em lançamento', 8.5, 94, 55, 'ufotable', 'Koyoharu Gotouge', '24 min por episódio', 'catálogo e temporadas disponíveis podem variar por plataforma.', 'depois de ter a família massacrada e ver Nezuko transformada em demônio, Tanjiro entra para os caçadores em busca de uma cura. A história mistura vingança, compaixão e batalhas contra criaturas cada vez mais cruéis.', 'https://cdn.myanimelist.net/images/anime/1286/99889.jpg', 'https://cdn.myanimelist.net/images/anime/1286/99889l.jpg');
