INSERT IGNORE INTO obra (id, titulo, tipo, ano, status, nota, popularidade, episodios, estudio, autor, duracao, plataformas_nota, sinopse, capa, banner) VALUES ('chainsaw-man', 'Chainsaw Man', 'mangá', 2018, 'em lançamento', 8.8, 93, 180, 'MAPPA', 'Tatsuki Fujimoto', '24 min por episódio', 'leitura gratuita/oficial pode ter capítulos limitados conforme a plataforma.', 'endividado e sozinho, Denji sobrevive caçando demônios ao lado de Pochita, até uma traição mudar seu corpo para sempre. Como Chainsaw Man, ele ganha uma chance de viver melhor, mas descobre que desejos simples também atraem monstros.', 'https://cdn.myanimelist.net/images/manga/3/216464.jpg', 'https://cdn.myanimelist.net/images/manga/3/216464l.jpg');
