INSERT IGNORE INTO obra (id, titulo, tipo, ano, status, nota, popularidade, episodios, estudio, autor, duracao, plataformas_nota, sinopse, capa, banner) VALUES ('one-piece', 'One Piece', 'anime', 1999, 'em lançamento', 8.9, 92, 1100, 'Toei Animation', 'Eiichiro Oda', '24 min por episódio', 'episódios e arcos disponíveis variam por plataforma.', 'Monkey D. Luffy parte para o mar decidido a encontrar o lendário One Piece e se tornar o Rei dos Piratas. No caminho, reúne uma tripulação improvável e encara ilhas, governos e rivais que testam o verdadeiro sentido de liberdade.', 'https://cdn.myanimelist.net/images/anime/6/73245.jpg', 'https://cdn.myanimelist.net/images/anime/6/73245l.jpg');
