INSERT IGNORE INTO obra (id, titulo, tipo, ano, status, nota, popularidade, episodios, estudio, autor, duracao, plataformas_nota, sinopse, capa, banner) VALUES ('omniscient-reader', 'Omniscient Reader', 'manhwa', 2020, 'em lançamento', 8.6, 89, 210, 'REDICE Studio', 'singNsong e Sleepy-C', 'capítulos semanais', 'a adaptação em webtoon tem leitura oficial em inglês no WEBTOON.', 'Kim Dokja era o único leitor fiel de uma web novel apocalíptica, até o mundo real começar a seguir exatamente aquela história. Conhecer os eventos futuros vira sua maior vantagem, mas sobreviver exige mudar o roteiro.', 'https://a.storyblok.com/f/178900/1064x1505/e6bb5351c9/omniscient-reader-kv.png/m/filters:quality(85)format(webp)', 'https://a.storyblok.com/f/178900/1064x1505/e6bb5351c9/omniscient-reader-kv.png/m/filters:quality(85)format(webp)');
