INSERT IGNORE INTO obra (id, titulo, tipo, ano, status, nota, popularidade, episodios, estudio, autor, duracao, plataformas_nota, sinopse, capa, banner) VALUES ('heaven-official', 'Heaven Official''s Blessing', 'manhua', 2017, 'finalizado', 8.8, 84, 244, 'Bilibili', 'Mo Xiang Tong Xiu e STARember', 'capítulos digitais', 'a disponibilidade oficial em inglês do manhua mudou após o encerramento do Bilibili Comics internacional.', 'Xie Lian, um príncipe banido e ridicularizado pelos céus, ascende pela terceira vez sem prestígio nem seguidores. Em novas missões no mundo mortal, ele encontra Hua Cheng, um poderoso rei fantasma ligado ao seu passado.', 'https://cdn.myanimelist.net/images/manga/3/233331.jpg', 'https://cdn.myanimelist.net/images/manga/3/233331l.jpg');
