INSERT IGNORE INTO obra (id, titulo, tipo, ano, status, nota, popularidade, episodios, estudio, autor, duracao, plataformas_nota, sinopse, capa, banner) VALUES ('spy-family', 'Spy x Family', 'anime', 2022, 'em lançamento', 8.6, 91, 37, 'WIT Studio e CloverWorks', 'Tatsuya Endo', '24 min por episódio', 'temporadas disponíveis podem variar por serviço e região.', 'para impedir uma crise internacional, o espião Twilight precisa formar uma família falsa e infiltrar a filha em uma escola de elite. O plano parece funcionar, exceto pelo detalhe de que sua esposa é assassina e sua filha lê mentes.', 'https://cdn.myanimelist.net/images/anime/1441/122795.jpg', 'https://cdn.myanimelist.net/images/anime/1441/122795l.jpg');
